import{_ as i,o as a,c as e,an as t}from"./chunks/framework.BdQmZfLw.js";const r=JSON.parse('{"title":"GPU 与精度","description":"","frontmatter":{},"headers":[],"relativePath":"gpu.md","filePath":"gpu.md","lastUpdated":null}'),l={name:"gpu.md"};function n(p,s,h,o,d,k){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="GPU-与精度" tabindex="-1">GPU 与精度 <a class="header-anchor" href="#GPU-与精度" aria-label="Permalink to &quot;GPU 与精度 {#GPU-与精度}&quot;">​</a></h1><p>MicroMagnetic.jl 默认在 CPU 上运行,并通过 <a href="https://github.com/JuliaGPU/KernelAbstractions.jl" target="_blank" rel="noreferrer">KernelAbstractions.jl</a> 支持 NVIDIA、AMD、Intel 和 Apple GPU。本页说明三个会话级设置——<strong>后端</strong>、<strong>精度</strong>与 <strong>线程组大小</strong>——以及一条需要牢记的规则:</p><div class="warning custom-block"><p class="custom-block-title">设置是构造期默认值</p><p><code>set_backend</code>、<code>set_precision</code> 和 <code>set_groupsize</code> 只影响<strong>之后</strong>创建的模拟。 <code>Sim</code> 在构造时把精度冻结进类型、把后端冻结进数据;之后再改全局设置, 不会触碰已经存在的模拟。</p></div><h2 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to &quot;后端 {#后端}&quot;">​</a></h2><p>按<a href="./install">安装页</a>的说明装好 GPU 包后,用 <code>@using_gpu</code> 宏加载——它会自动 导入当前环境中可用的后端包:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MicroMagnetic</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@using_gpu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 有 CUDA/AMDGPU/oneAPI/Metal 则加载之,否则留在 CPU</span></span></code></pre></div><p>该宏会自动切换默认后端。如需手动控制:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cuda&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 之后的分配进入 GPU</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cpu&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 回到 CPU</span></span></code></pre></div><p>已有模拟存在时调用 <code>set_backend</code> 会打印警告——正在运行的模拟数据保持原地不动。</p><h2 id="精度" tabindex="-1">精度 <a class="header-anchor" href="#精度" aria-label="Permalink to &quot;精度 {#精度}&quot;">​</a></h2><p>默认工作精度是 <code>Float64</code>。单精度在消费级 GPU 上通常能翻倍吞吐 (GeForce 卡 FP64 吞吐只有 FP32 的 1/32),并把显存占用减半:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_precision</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Float32)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 这行之后创建的模拟使用 Float32</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sim </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Sim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mesh; driver</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LLG&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>允许的取值为 <code>Float64</code>、<code>Float32</code> 和 <code>AbstractFloat</code>:</p><ul><li><p><code>Float64</code> / <code>Float32</code> —— 生产运行的具象精度;</p></li><li><p><code>AbstractFloat</code> —— <strong>符号模式</strong>,只有本征值分析工作流使用,允许参数携带符号项。 常规模拟在该模式下会失败,尤其在 GPU 上(设备数组不接受抽象元素类型)。</p></li></ul><div class="tip custom-block"><p class="custom-block-title">先设精度,再建模拟</p><p>精度在构造时冻结进模拟类型,所以要在 <code>Sim(...)</code> / <code>CubicMesh(...)</code> / <code>FDMesh(...)</code> <strong>之前</strong>调用 <code>set_precision</code>。不支持同一会话内混用精度。</p></div><h3 id="本征值分析的例外" tabindex="-1">本征值分析的例外 <a class="header-anchor" href="#本征值分析的例外" aria-label="Permalink to &quot;本征值分析的例外 {#本征值分析的例外}&quot;">​</a></h3><p>本征值分析需要符号模式,它会修改<strong>整个会话</strong>的全局精度且不会自动恢复。 做完本征值计算后,在创建后续模拟之前先恢复具象精度:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ... set_precision(AbstractFloat) 下的本征值分析 ...</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_precision</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Float64)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 下一个模拟之前恢复</span></span></code></pre></div><p>完整工作流见<a href="./eigen/eigenmodes">本征模分析</a>页。</p><h2 id="线程组大小" tabindex="-1">线程组大小 <a class="header-anchor" href="#线程组大小" aria-label="Permalink to &quot;线程组大小 {#线程组大小}&quot;">​</a></h2><p><code>set_groupsize</code> 控制 GPU kernel 发射时的线程组大小(默认 256)。它是纯性能 旋钮——不影响任何计算结果:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_groupsize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">128</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 只有 profiling 建议时才调</span></span></code></pre></div><h2 id="查看当前状态" tabindex="-1">查看当前状态 <a class="header-anchor" href="#查看当前状态" aria-label="Permalink to &quot;查看当前状态 {#查看当前状态}&quot;">​</a></h2><p><code>using MicroMagnetic</code> 后的启动信息会报告当前后端。脚本里可以通过模拟本身 确认冻结的精度:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sim </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Sim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mesh; driver</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LLG&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">eltype</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sim</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">spin)                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 该模拟的工作精度</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">先测量,再调参</p><p>任何性能相关的事——组大小、精度、后端——都先用 <code>MicroMagnetic.timer</code> 前后测量;报告长什么样见<a href="./basics">基础页</a>的 Timings 一节。</p></div>`,26)])])}const g=i(l,[["render",n]]);export{r as __pageData,g as default};
